context.log_level = 'error'

def mod_inverse(a, p):
    if a == 0:
        raise Exception("Division by zero")
    if a < 0:
        return p - mod_inverse(-a, p)
    t, newt = 0, 1
    r, newr = p, a
    while newr != 0:
        quotient = r // newr
        t, newt = newt, t - quotient * newt
        r, newr = newr, r - quotient * newr
    if r > 1:
        raise Exception("Not invertible")
    if t < 0:
        t += p
    return t

def point_add(P1, P2, a, p):
    if P1 is None:
        return P2
    if P2 is None:
        return P1

    x1, y1 = P1
    x2, y2 = P2

    if x1 == x2 and y1 == (-y2 % p):
        return None

    if P1 != P2:
        slope = ((y2 - y1) * mod_inverse(x2 - x1, p)) % p
    else:
        # Point doubling
        slope = ((3 * x1 * x1 + a) * mod_inverse(2 * y1, p)) % p

    x3 = (slope * slope - x1 - x2) % p
    y3 = (slope * (x1 - x3) - y1) % p

    return (x3, y3)

def scalar_multiply(k, P, a, p):
    result = None
    current = P
    k = int(k)

    while k:
        if k & 1:
            result = point_add(result, current, a, p)
        current = point_add(current, current, a, p)
        k >>= 1
    return result

