#!/usr/bin/env python3
from pwn import *
context.log_level = 'error'

def mod_inverse(a, p):
    return pow(a, p-2, p)

def point_add(P1, P2, a, p):
    if P1 is None:
        return P2
    if P2 is None:
        return P1

    x1, y1 = P1
    x2, y2 = P2

    if x1 == x2 and y1 == (-y2 % p):
        return None

    if P1 != P2:
        slope = ((y2 - y1) * mod_inverse(x2 - x1, p)) % p
    else:
        # Point doubling
        slope = ((3 * x1 * x1 + a) * mod_inverse(2 * y1, p)) % p

    x3 = (slope * slope - x1 - x2) % p
    y3 = (slope * (x1 - x3) - y1) % p

    return (x3, y3)

def scalar_multiply(k, P, a, p):
    if k == 0:
        return None
    elif k == 1:
        return P
    elif k % 2 == 0:
        return scalar_multiply(k//2, point_add(P, P, a, p), a, p)
    else:
        return point_add(P, scalar_multiply(k-1, P, a, p), a, p)

def find_private_key(G, Q, a, p, n):
    for k in range(n):
        if k % 100 == 0:
            print(f"Trying k = {k}")
        point = scalar_multiply(k, G, a, p)
        if point == Q:
            return k
    return None

def main():
    a = 1
    p = 14753
    n = 7919
    G = (1, 1)

    print("Connecting to server...")
    conn = remote('crypto.chal.csaw.io', 8000)
    conn.recvuntil(b'Public key: ')

    pubkey_str = conn.recvline().decode().strip()
    Q = tuple(map(int, pubkey_str.strip('()').split(', ')))
    print(f"Received public key: {Q}")

    conn.recvuntil(b'secret?\n')

    print("Finding private key...")
    priv_key = find_private_key(G, Q, a, p, n)
    print(f"Found private key: {priv_key}")

    print("Sending private key...")
    conn.sendline(str(priv_key).encode())

    print("Receiving response...")
    response = conn.recvall(timeout=2).decode()
    print(f"Server response: {response}")

if __name__ == '__main__':
    main()
